keywords=['\u6d77\u80fd','\u667a\u7b97','\u7b97\u529b','GPU','\u63a8\u7406','\u90e8\u7f72','\u6a21\u578b','\u5fae\u8c03','\u8bad\u7ec3','\u667a\u80fd\u4f53','\u77e5\u8bc6\u5e93','API','SSO','\u8ba1\u91cf','\u6743\u9650','\u8d44\u6e90','\u95e8\u6237','\u661f\u706b']
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.t=False; self.title=''; self.text=[]; self.cap=False
    def handle_starttag(self,tag,attrs):
        if tag=='title': self.t=True
        if tag in {'h1','h2','h3','p','li','td','th'}: self.cap=True
    def handle_endtag(self,tag):
        if tag=='title': self.t=False
        if tag in {'h1','h2','h3','p','li','td','th'}: self.cap=False
    def handle_data(self,data):
        s=' '.join(data.split())
        if not s: return
        if self.t: self.title += s
